public static String toDashCase(String key){
  StringBuilder sb=new StringBuilder(key.length());
  boolean l=false;
  for (int i=0; i < key.length(); i++) {
    char c=key.charAt(i);
    if (l && Character.isUpperCase(c)) {
      sb.append('-');
      c=Character.toLowerCase(c);
      l=false;
    }
 else {
      l=Character.isLowerCase(c);
    }
    sb.append(c);
  }
  return sb.toString();
}
